package org.sleepwell.app;
import org.junit.Test;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import static org.junit.Assert.*;
public final class TrackingDndOwnerTest {
 static final class Memory implements TrackingDndOwner.Store{TrackingDndLease value;String error="";boolean touched;int writes,failAt;public TrackingDndLease read(){return value;}public void save(TrackingDndLease lease){if(++writes==failAt)throw new IllegalStateException("Injected journal failure");value=lease;}public void error(String message){error=message;}public void touched(){touched=true;}}
 static final class Fake implements TrackingDndOwner.Port{boolean access=true,exact=true,failSchedule,failOff;int sequence,on,off,removed,schedules;final Map<String,String> rules=new HashMap<>();final Set<String> active=new HashSet<>(),disabled=new HashSet<>(),alarms=new HashSet<>();final List<String> calls=new ArrayList<>();public boolean access(){return access;}public boolean exact(){return exact;}public String create(String token){String id="rule"+(++sequence);rules.put(id,token);calls.add("create");return id;}public boolean owned(String id,String token){return token.equals(rules.get(id));}public boolean enabled(String id,String token){return owned(id,token)&&!disabled.contains(id);}public void on(String id,String token){assertTrue(owned(id,token));on++;calls.add("on");active.add(id);}public void off(String id,String token){assertTrue(owned(id,token));if(failOff)throw new IllegalStateException("OFF failed");off++;calls.add("off");active.remove(id);}public void remove(String id,String token){assertTrue(owned(id,token));removed++;rules.remove(id);}public void schedule(String token,long deadline){if(failSchedule)throw new IllegalStateException("Expiry failed");schedules++;calls.add("expiry");alarms.add(token+"/"+deadline);}public void cancel(String token,long deadline){alarms.remove(token+"/"+deadline);}public Map<String,String> ownedRules(){return new HashMap<>(rules);}}
 static final class Fixture{final Memory memory=new Memory();final Fake port=new Fake();int nonce;final TrackingDndOwner owner=new TrackingDndOwner(memory,port,()->"nonce"+(++nonce));void start(){owner.start("run",true,1000,1,()->true);}}
 @Test public void defaultOffNeverCreatesEnablesOrSchedules(){Fixture f=new Fixture();f.owner.start("run",false,1000,1,()->true);assertEquals(0,f.port.on+f.port.schedules+f.port.sequence);}
 @Test public void deniedPolicyDoesNotPretendToActivate(){Fixture f=new Fixture();f.port.access=false;assertThrows(IllegalStateException.class,f::start);assertNull(f.memory.value);assertEquals(0,f.port.on);}
 @Test public void missingExactSafeguardPreventsActivation(){Fixture f=new Fixture();f.port.exact=false;assertThrows(IllegalStateException.class,f::start);assertEquals(0,f.port.sequence);}
 @Test public void expiryIsPreparedBeforeAnyActivation(){Fixture f=new Fixture();f.start();assertEquals(List.of("create","expiry","on"),f.port.calls);assertTrue(f.memory.value.active);assertTrue(f.memory.touched);assertEquals(1000+TrackingDndLease.WINDOW,f.memory.value.deadline);}
 @Test public void staleAdmissionCannotCreateRule(){Fixture f=new Fixture();f.owner.start("run",true,1000,1,()->false);assertEquals(0,f.port.sequence);}
 @Test public void stopRemovesOnlyMatchingRunAndItsExpiry(){Fixture f=new Fixture();f.start();f.owner.stop("other");assertEquals(0,f.port.off);f.owner.stop("run");assertNull(f.memory.value);assertTrue(f.port.active.isEmpty());assertTrue(f.port.alarms.isEmpty());}
 @Test public void staleExpiryCannotStopReplacementLease(){Fixture f=new Fixture();f.start();TrackingDndLease old=f.memory.value;f.owner.start("new-run",true,2000,1,()->true);TrackingDndLease next=f.memory.value;int off=f.port.off;f.owner.expire(old.token,old.deadline,old.deadline,1);assertEquals(off,f.port.off);assertSame(next,f.memory.value);}
 @Test public void staleStartCannotRemoveCurrentLease(){Fixture f=new Fixture();f.start();TrackingDndLease lease=f.memory.value;f.owner.start("old",true,2000,1,()->false);assertSame(lease,f.memory.value);assertEquals(0,f.port.off);}
 @Test public void earlyOrStaleDeadlineCannotRemoveLease(){Fixture f=new Fixture();f.start();TrackingDndLease lease=f.memory.value;f.owner.expire(lease.token,lease.deadline,lease.deadline-1,1);f.owner.expire(lease.token,lease.deadline-1,lease.deadline,1);assertSame(lease,f.memory.value);}
 @Test public void actualExpiryRemovesOwnedRule(){Fixture f=new Fixture();f.start();TrackingDndLease lease=f.memory.value;f.owner.expire(lease.token,lease.deadline,lease.deadline,1);assertNull(f.memory.value);assertEquals(1,f.port.off);}
 @Test public void renewalNeverReassertsRuleAndCancelsOldDeadline(){Fixture f=new Fixture();f.start();TrackingDndLease before=f.memory.value;f.owner.renew("run",61000,1,()->true);assertEquals(1,f.port.on);assertEquals(61000+TrackingDndLease.WINDOW,f.memory.value.deadline);assertFalse(f.port.alarms.contains(before.token+"/"+before.deadline));assertEquals(1,f.port.alarms.size());}
 @Test public void unchangedHardDeadlineNeverCancelsItsOwnSafeguard(){Fixture f=new Fixture();f.start();f.memory.value=f.memory.value.renewed(f.memory.value.hard);f.port.alarms.clear();f.port.alarms.add(f.memory.value.token+"/"+f.memory.value.hard);f.owner.renew("run",f.memory.value.hard-1000,1,()->true);assertEquals(1,f.port.alarms.size());}
 @Test public void failedRenewalJournalRetainsOldExpiry(){Fixture f=new Fixture();f.start();TrackingDndLease old=f.memory.value;f.memory.failAt=f.memory.writes+1;assertThrows(IllegalStateException.class,()->f.owner.renew("run",61000,1,()->true));assertSame(old,f.memory.value);assertEquals(Set.of(old.token+"/"+old.deadline),f.port.alarms);}
 @Test public void expirySchedulingFailureNeverActivates(){Fixture f=new Fixture();f.port.failSchedule=true;assertThrows(IllegalStateException.class,f::start);assertEquals(0,f.port.on);assertTrue(f.port.rules.isEmpty());}
 @Test public void initialJournalFailureCleansInactiveRule(){Fixture f=new Fixture();f.memory.failAt=1;assertThrows(IllegalStateException.class,f::start);assertEquals(0,f.port.on);assertTrue(f.port.rules.isEmpty());}
 @Test public void writeAfterOnFailureStillRequestsImmediateCleanup(){Fixture f=new Fixture();f.memory.failAt=2;assertThrows(IllegalStateException.class,f::start);assertEquals(1,f.port.on);assertEquals(1,f.port.off);assertTrue(f.port.active.isEmpty());}
 @Test public void cleanupFailureRetainsOwnerForHonestRetry(){Fixture f=new Fixture();f.start();TrackingDndLease lease=f.memory.value;f.port.failOff=true;assertThrows(IllegalStateException.class,()->f.owner.stop("run"));assertSame(lease,f.memory.value);f.port.failOff=false;f.owner.stop("run");assertNull(f.memory.value);}
 @Test public void processRecoveryDoesNotRemoveLiveNewlyAdmittedLease(){Fixture f=new Fixture();f.start();TrackingDndLease lease=f.memory.value;f.owner.recover(run->run.equals("run"),1,2000);assertSame(lease,f.memory.value);assertEquals(0,f.port.off);}
 @Test public void processAndBootRecoveryOnlyDeactivateNeverActivate(){Fixture f=new Fixture();f.start();f.owner.recover(run->false,1,2000);assertNull(f.memory.value);assertEquals(1,f.port.on);f.start();f.owner.recover(run->true,2,2000);assertNull(f.memory.value);assertEquals(2,f.port.on);}
 @Test public void disabledRuleIsNotReenabledByHeartbeat(){Fixture f=new Fixture();f.start();f.port.disabled.add(f.memory.value.rule);f.owner.renew("run",61000,1,()->true);assertNull(f.memory.value);assertEquals(1,f.port.on);assertFalse(f.memory.error.isEmpty());}
 @Test public void hardLimitStopsEvenIfRecordingPortStillClaimsActive(){Fixture f=new Fixture();f.start();f.owner.renew("run",f.memory.value.hard,1,()->true);assertNull(f.memory.value);}
}
